+        intersectsTriangle = polygon2D.intersectsTriangle(
+            quantizeLon(0.5),
+            quantizeLat(0),
+            quantizeLon(1),
+            quantizeLat(0.5),
+            quantizeLon(0.5),
+            quantizeLat(0.75)
+        );
+        assertTrue(intersectsTriangle);
+        assertTrue(containsTriangle);
+        // 1 shared point
+        containsTriangle = polygon2D.containsTriangle(
+            quantizeLon(0.5),
+            quantizeLat(0.5),
+            quantizeLon(0.5),
+            quantizeLat(0),
+            quantizeLon(0.75),
+            quantizeLat(0.75)
+        );
+        intersectsTriangle = polygon2D.intersectsTriangle(
+            quantizeLon(0.5),
+            quantizeLat(0),
+            quantizeLon(1),
+            quantizeLat(0.5),
+            quantizeLon(0.5),
+            quantizeLat(0.75)
+        );
+        assertTrue(intersectsTriangle);
+        assertTrue(containsTriangle);
+        // 1 shared point but out
+        containsTriangle = polygon2D.containsTriangle(
+            quantizeLon(1),
+            quantizeLat(0.5),
+            quantizeLon(2),
+            quantizeLat(0),
+            quantizeLon(2),
+            quantizeLat(2)
