+            quantizeLat(0.5),
+            quantizeLon(2),
+            quantizeLat(0),
+            quantizeLon(2),
+            quantizeLat(2)
+        );
+        assertTrue(intersectsTriangle);
+        assertFalse(containsTriangle);
+        // 1 shared point but crossing
+        containsTriangle = polygon2D.containsTriangle(
+            quantizeLon(0.5),
+            quantizeLat(0),
+            quantizeLon(2),
+            quantizeLat(0.5),
+            quantizeLon(0.5),
+            quantizeLat(1)
