+            quantizeLat(0),
+            quantizeLon(2),
+            quantizeLat(0.5),
+            quantizeLon(0.5),
+            quantizeLat(1)
+        );
+        assertTrue(intersectsTriangle);
+        assertFalse(containsTriangle);
+        // share one edge
+        containsTriangle = polygon2D.containsTriangle(
+            quantizeLon(0),
+            quantizeLat(0),
+            quantizeLon(0),
+            quantizeLat(1),
+            quantizeLon(0.5),
+            quantizeLat(0.5)
