+    /** test line intersection */
+    public void testLinesIntersect() {
+        Rectangle rect = nextBoxNotCrossingDateline();
+        // simple case; test intersecting diagonals
+        // note: we don't quantize because the tessellator operates on non quantized vertices
+        assertTrue(
+            XTessellator.linesIntersect(
+                rect.minLon,
+                rect.minLat,
+                rect.maxLon,
+                rect.maxLat,
+                rect.maxLon,
+                rect.minLat,
+                rect.minLon,
+                rect.maxLat
+            )
+        );
+        // test closest encoded value
+        assertFalse(
+            XTessellator.linesIntersect(
+                rect.minLon,
+                rect.maxLat,
+                rect.maxLon,
+                rect.maxLat,
+                rect.minLon - 1d,
+                rect.minLat,
+                rect.minLon - 1,
+                rect.maxLat
+            )
+        );
+    }
