+        sb.append(" =\n            \"");
+        char separator = name.equalsIgnoreCase("geojson") ? ']' : ',';
+        char[] x = line.toCharArray();
+        int index = 0;
+        int prev = 0;
+        while (index < x.length - 120) {
+            index += 119;
+            while (x[index] != separator)
+                index--;
+            if (x[index + 1] == ',') index++;
+            sb.append(x, prev, index - prev + 1);
+            sb.append("\"\n            + \"");
+            index++;
+            while (x[index] == ' ')
+                index++;
+            prev = index;
+        }
+        sb.append(x, prev, x.length - prev);
+        sb.append("\";\n");
+        return sb.toString();
+    }
