+                    }
+                    index = getIndex(length, ++j + offset);
+                }
+            }
+        }
+        if (p.getHoles() != null && p.getHoles().length > 0) {
+            for (Polygon hole : p.getHoles()) {
+                if (isEdgeFromPolygon(hole, aLon, aLat, bLon, bLat)) {
+                    return true;
+                }
+            }
+        }
+        return false;
+    }
