+        // POINT(5, 5) inside the indexed polygon
+        Field[] pointFields = LatLonShape.createIndexableFields(FIELDNAME, 5, 5);
+        int numDocs = random().nextInt(1000);
+        // index the same multi geometry many times
+        for (int i = 0; i < numDocs; i++) {
